SELECT 'b2a17ccc-e65c-4caa-bc3a-27b218841697', (SELECT id FROM categories WHERE slug = 'slicer'), 'Slicer HSS Nashiji Finish 215mm', 'slicer-hss-nashiji-finish-215mm', 'Slicer knife adalah pisau dapur yang dirancang untuk memotong daging, roast, dan bahan bertekstur lembut dengan irisan tipis dan rapi. Menggunakan baja HSS (High Speed Steel) yang unggul dalam ketahanan aus dan daya tahan ketajaman, pisau ini mampu memberikan hasil potong yang halus dan konsisten, bahkan dalam penggunaan intensif. Bilahnya yang panjang dan ramping memudahkan satu tarikan potong tanpa merusak struktur daging, sementara pegangan ergonomis memastikan kenyamanan dan kontrol optimal bagi penggunanya.', NULL, 385000, 425000, 'IDR', NULL, 'sale', 1, 500, 1, NOW(), NOW()
WHERE NOT EXISTS (SELECT 1 FROM products WHERE slug = 'slicer-hss-nashiji-finish-215mm');
INSERT INTO products (id, category_id, name, slug, description, care_instructions, price, compare_at_price, currency, maker, badge, stock, weight, is_active, created_at, updated_at)
SELECT 'db420d1a-f2a5-4823-a44c-b6e5762e93b2', (SELECT id FROM categories WHERE slug = 'k-tip-gyuto'), 'K-Tip Gyuto HSS Nashiji Finish 205mm', 'k-tip-gyuto-hss-nashiji-finish-205mm', 'K-tip gyuto adalah pisau dapur Jepang yang memadukan karakter serbaguna dari gyuto dengan ujung khas “kiritsuke tip” yang runcing dan presisi tinggi. Menggunakan baja HSS (High Speed Steel) yang unggul dalam ketahanan aus dan daya tahan ketajaman, pisau ini memberikan performa potong yang konsisten, tajam, dan responsif untuk berbagai teknik seperti slicing, chopping, hingga detail work yang membutuhkan akurasi tinggi. Desain ujung K-tip memungkinkan kontrol lebih baik saat memotong bahan kecil atau membuat potongan presisi, sementara bilah yang panjang dan sedikit melengkung tetap menjaga alur potong yang halus. Dipadukan dengan pegangan ergonomis, K-tip gyuto menjadi pilihan ideal bagi chef', NULL, 910000, 950000, 'IDR', NULL, 'sale', 1, 500, 1, NOW(), NOW()
WHERE NOT EXISTS (SELECT 1 FROM products WHERE slug = 'k-tip-gyuto-hss-nashiji-finish-205mm');
