INSERT INTO products (id, category_id, name, slug, description, care_instructions, price, compare_at_price, currency, maker, badge, stock, weight, is_active, created_at, updated_at)
SELECT '66f1262a-0db6-41b7-af21-4fe533b12f54', (SELECT id FROM categories WHERE slug = 'k-tip-gyuto'), 'K-tip Gyuto N695 Stainless Steel 210mm', 'k-tip-gyuto-n695-stainless-steel-210mm', 'K-tip gyuto adalah pisau dapur Jepang yang memadukan karakter serbaguna dari gyuto dengan ujung khas “kiritsuke tip” yang runcing dan presisi tinggi. Menggunakan baja N695 stainless steel yang dikenal tahan karat, mudah dirawat, dan memiliki ketajaman yang stabil, pisau ini memberikan performa potong yang konsisten, presisi, dan andal untuk berbagai teknik seperti slicing, chopping, hingga detail work yang membutuhkan akurasi tinggi. Desain ujung K-tip memungkinkan kontrol lebih baik saat menangani bahan kecil atau membuat potongan halus, sementara bilah yang panjang dan sedikit melengkung menjaga alur potong tetap mulus. Dipadukan dengan pegangan ergonomis, K-tip gyuto N695 menjadi pilihan ideal bagi penggunanya.', NULL, 1810000, 1850000, 'IDR', NULL, 'sale', 1, 300, 1, NOW(), NOW()
WHERE NOT EXISTS (SELECT 1 FROM products WHERE slug = 'k-tip-gyuto-n695-stainless-steel-210mm');
INSERT INTO products (id, category_id, name, slug, description, care_instructions, price, compare_at_price, currency, maker, badge, stock, weight, is_active, created_at, updated_at)
SELECT '1badf2aa-2d0c-4246-8321-b27289d888e8', (SELECT id FROM categories WHERE slug = 'gyuto'), 'Gyuto Kurouchi High Speed Steel 235mm', 'gyuto-kurouchi-high-speed-steel-235mm', 'Gyuto Kurouchi – 235mmPisau Gyuto adalah interpretasi Jepang dari chef’s knife yang dirancang untuk serba guna di dapur profesional maupun rumahan. Dengan bilah sepanjang 235mm, pisau ini mampu menangani berbagai teknik pemotongan, mulai dari memotong daging besar hingga mengiris sayuran halus dengan presisi tinggi.
Finishing Kurouchi menghadirkan tampilan hitam alami yang merupakan hasil dari proses tempa tradisional. Lapisan ini bukan hanya memberikan karakter rustic dan elegan, tetapi juga berfungsi sebagai perlindungan tambahan terhadap oksidasi ringan.
Fungsi Utama
Memotong dan mengiris daging merah, ikan, dan unggas dengan mudah.
Mengolah berbagai jenis sayuran keras maupun lembut.
Mencincang bumbu dan rempah dengan kontrol penuh.
Membuat potongan tipis slicing untuk hidangan presisi.
Keunggulan Pisau Gyuto Kurouchi
Bilah Tajam & Presisi – Terbuat dari baja berkualitas, memberikan ketajaman luar biasa yang tahan lama.
Finishing Kurouchi Tradisional – Memberikan perlindungan sekaligus estetika klasik Jepang.
Desain Ergonomis – Seimbang dan nyaman digenggam, mengurangi rasa lelah saat pemakaian intensif.
Serbaguna – Cocok digunakan baik oleh koki profesional maupun pecinta masak rumahan yang mengutamakan kualitas.
Pisau ini bukan sekadar alat dapur, melainkan perpaduan seni tradisi Jepang dan fungsionalitas modern, menjadikannya pilihan tepat bagi siapa pun yang mengutamakan presisi, ketajaman, dan keindahan dalam setiap potongan.', NULL, 910000, 950000, 'IDR', NULL, 'sale', 1, 300, 1, NOW(), NOW()
WHERE NOT EXISTS (SELECT 1 FROM products WHERE slug = 'gyuto-kurouchi-high-speed-steel-235mm');
